export async function operatorOpenSwaggerUi(provider, addonIdOrName) {
  const operator = await Operator.getDetails(provider, addonIdOrName);
  const swaggerUrl = operator.api?.swaggerUrl;
  if (swaggerUrl == null) {
    throw new Error(`No Swagger UI available for ${operator.addonId}`);
  }
  await openBrowser(swaggerUrl, `Opening ${styleText('blue', operator.addonId)} Swagger UI in the browser…`);
}

